def curriculum_for(name, keys, activity):
    case, prepare, deliverable, complication, evidence, sequence = PATHS[name]
    # Learning sequence may use a role's documented adjacent skill (e.g. project
    # coordination in HR); it does not silently add a scored role requirement.
    ordered = [key for key in sequence.split() if key in keys]
    ordered.extend(key for key in keys if key not in ordered)
    prefix = name.lower().replace(" ", "-").replace("&", "and")
    def milestone(suffix, title, outcome, artifact, checks, prerequisites):
        return {"id": prefix + "-" + suffix, "title": title, "outcome": outcome,
                "skill_keys": ordered, "deliverable": artifact,
                "checks": checks, "prerequisites": [prefix + "-" + value for value in prerequisites]}
    return {
        "case": case + ".",
        "skill_sequence": ordered,
        "foundation": {
            "milestones": [
                milestone("f1", "Prepare the case", prepare + ".", "A case brief with inputs, assumptions and acceptance checks.", [prepare + ".", "Identify what is known, missing and assumed in this case."], []),
                milestone("f2", activity["title"], activity["instructions"], activity["title"] + ": a reproducible first version with supporting notes.", activity["rubric"], ["f1"]),
            ],
            "assessment": {"difficulty_min": 1, "difficulty_max": 2, "note": "Introductory knowledge checks. Practical work is reviewed separately when shared with an assigned mentor; a quiz score does not grade the practical work."},
        },
        "intermediate": {
            "milestones": [
                milestone("i1", "Investigate a complication", complication + ".", "An annotated case analysis comparing at least two defensible responses.", ["Trace the complication to the stated inputs and constraints.", evidence + "."], ["f2"]),
                milestone("i2", "Deliver and defend the decision", "Combine the role's skills to produce a reasoned, testable response to the case.", deliverable + ".", [evidence + ".", "Include the original artifact, verification results, limitations and a revision after feedback."], ["i1"]),
            ],
            "assessment": {"difficulty_min": 3, "difficulty_max": 3, "note": "Applied scenario questions at an authored intermediate level. Practical judgement is reviewed separately against the case rubric; this is not a professional qualification."},
        },
        "note": "Use synthetic or appropriately licensed public inputs. Do not submit private employer, employee or customer data. Learning milestones do not certify job readiness or authorize regulated work.",
    }
